300:   function action(type) {
301:     const p = game.plants[game.selected];
302:     if (!p) return;
303:     if (type === 'water') {
304:       if (!p.alive || p.moisture > 82 || game.water < 1) return;
305:       p.moisture = Math.min(92, p.moisture + 45); game.water--; p.checked = true; game.spent += 150;
306:       log(`<b>Riego aplicado.</b> Planta ${p.id} · sustrato al ${p.moisture}%.`);
307:       showToast(`Planta ${p.id}: riego aplicado.`);
308:     }
309:     if (type === 'feed') {
310:       if (!p.alive || p.nutrition > 88 || game.nutrients < 1) return;
311:       p.nutrition = Math.min(100, p.nutrition + 42); game.nutrients--; p.checked = true; game.spent += 900;
312:       log(`<b>Nutrición equilibrada.</b> Planta ${p.id} recibió una dosis.`);
313:       showToast(`Planta ${p.id}: aporte aplicado.`);
314:     }
315:     if (type === 'inspect') {
316:       if (!p.alive) return;
317:       p.checked = true;
318:       const msg = p.moisture < 30 ? 'Sustrato seco' : p.moisture > 78 ? 'Humedad alta' : p.health < 60 ? 'Vitalidad baja' : 'Sin señales de estrés';
319:       log(`<b>Inspección · Planta ${p.id}.</b> ${msg}.`);
320:       showToast(`Planta ${p.id}: ${msg.toLowerCase()}.`);
321:     }
322:     if (type === 'vent') {
323:       if (game.energy < 1 || game.vented) return;
324:       game.energy--; game.temp = Math.max(19, game.temp - 3); game.humidity = Math.max(40, game.humidity - 8); game.vented = true; game.spent += 90;
325:       log('<b>Ventilación activada.</b> El ambiente se renovó.');
326:       showToast('Ambiente renovado.');
327:     }
328:     if (type === 'harvest') {
329:       if (!p.alive || p.age < 67) return;
330:       const grams = Math.round(10 + p.health * .55 + Math.min(8, (p.age - 67) * .4));
331:       p.alive = false; game.harvested++; game.harvestYield += grams; game.spent += 1200;
332:       const quality = p.health > 75 ? 'calidad excelente' : p.health > 50 ? 'calidad equilibrada' : 'calidad modesta';
333:       log(`<b>Planta ${p.id} cosechada.</b> ${grams} g · ${quality}.`, 'success');
334:       showToast(`¡${grams} g cosechados! ${quality}.`);
335:     }
336:     saveAndRefresh();
337:   }
