662:   function envSeries(week) {
663:     const seed = week * 17;
664:     const tempBase = 23.2 + Math.sin(week / 1.7) * 1.9 - (week > 5 ? .7 : 0);
665:     const humBase = 64 - week * 1.9 + (week > 8 ? 1.2 : 0);
666:     return Array.from({ length: 7 }, (_, i) => {
667:       const wave = Math.sin((seed + i * 3.1)) * 0.9;
668:       const temp = +(tempBase + wave + (i % 2 ? .4 : -.2)).toFixed(1);
669:       const hum = Math.round(humBase - wave * 1.2 + (i % 3 ? 1 : -1));
670:       const svp = 0.6108 * Math.exp(17.27 * temp / (temp + 237.3));
671:       return { d: i + 1, temp, hum, vpd: +(svp * (1 - hum / 100)).toFixed(2) };
672:     });
673:   }
