675:   function envChartSVG(week) {
676:     const data = envSeries(week);
677:     const W = 620, H = 170, x0 = 30, x1 = 602, y0 = 12, y1 = 138;
678:     const x = i => x0 + (x1 - x0) * i / 6;
679:     const yT = v => y1 - (v - 16) / 16 * (y1 - y0);
680:     const yH = v => y1 - (v - 28) / 52 * (y1 - y0);
681:     const yV = v => y1 - (Math.max(.3, Math.min(2.2, v)) - .3) / 1.9 * (y1 - y0);
682:     const line = (key, fn) => data.map((p, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${fn(p[key]).toFixed(1)}`).join(' ');
683:     const grid = [0, 1, 2, 3, 4].map(i => {
684:       const yy = y0 + (y1 - y0) * i / 4;
685:       const val = (16 + (4 - i) * 4);
686:       return `<line x1="${x0}" y1="${yy}" x2="${x1}" y2="${yy}"/><text class="chart-axis" x="${x0 - 6}" y="${yy + 2.5}" text-anchor="end">${val}°</text>`;
687:     }).join('');
688:     const labels = ['L', 'M', 'X', 'J', 'V', 'S', 'D'].map((d, i) => `<text class="chart-axis" x="${x(i)}" y="${H - 5}" text-anchor="middle">${d}</text>`).join('');
689:     const dots = data.map((p, i) => `<circle class="chart-dot" cx="${x(i)}" cy="${yT(p.temp)}" r="2.4" fill="#e8b56a"/>`).join('');
690:     return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Temperatura, humedad y VPD de la semana ${week}">
691:       <defs><linearGradient id="tempFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#e8b56a" stop-opacity=".26"/><stop offset="1" stop-color="#e8b56a" stop-opacity="0"/></linearGradient></defs>
692:       <g class="chart-grid">${grid}</g>
693:       <path class="chart-area-temp" d="${line('temp', yT)} L${x(6)},${y1} L${x0},${y1} Z"/>
694:       <path class="chart-line temp" d="${line('temp', yT)}"/>
695:       <path class="chart-line hum" d="${line('hum', yH)}"/>
696:       <path class="chart-line vpd" d="${line('vpd', yV)}"/>
697:       ${dots}${labels}
698:     </svg>`;
