.br-bars b{font:500 6.5px var(--mono);color:#aab69a;text-align:right;white-space:nowrap}
.br-stats{display:flex;justify-content:space-between;gap:4px;border-top:1px solid rgba(235,241,214,.06);border-bottom:1px solid rgba(235,241,214,.06);padding:5px 0;margin-bottom:5px}
.br-stats span{font:400 5.8px var(--mono);color:#707a62;text-align:center;line-height:1.4}
