.br-use:hover{border-color:rgba(216,242,107,.3);color:var(--lime);background:rgba(216,242,107,.05)}
.batch-foot{display:flex;justify-content:space-between;gap:14px;font:400 6px var(--mono);letter-spacing:.03em;color:#6c755e;margin-top:8px;flex-wrap:wrap;position:relative;z-index:1}

.timelapse-band{margin-top:10px;border-top:1px solid var(--line);padding-top:9px;position:relative;z-index:1}
