.tl-phases{display:flex;gap:2px;height:26px}
.tl-phase{width:var(--w);position:relative;display:flex;flex-direction:column;justify-content:flex-end;padding:2px 4px;border-radius:4px 4px 0 0;background:rgba(235,241,214,.035);border-bottom:1px solid rgba(235,241,214,.08);min-width:0;overflow:hidden}
