function commandScore(e,q){
 const l=norm(e.label), m=norm(e.meta), h=norm(e.label+' '+e.meta+' '+(e.keywords||''));
 const words=q.split(/\s+/).filter(Boolean);
 if (!words.every(w=>h.includes(w))) return -1;
 let s=0;
 if (l===q) s+=100; else if (l.startsWith(q)) s+=60; else if (l.includes(q)) s+=30;
 words.forEach(w=>{ if(m.includes(w))s+=4; if(l.includes(w))s+=8;});
 s+= e.type==='view'?6:0;
 return s;
}
