/* ==========================================================================
   BÚSQUEDA GLOBAL · COMMAND PALETTE
   ========================================================================== */
.command-backdrop{align-items:flex-start;justify-content:center;padding:7vh 16px 20px;background:rgba(4,6,3,.74);backdrop-filter:blur(14px);z-index:90}
.command-panel{width:min(700px,100%);background:linear-gradient(165deg,#151b10,#0a0e07 72%);border:1px solid rgba(216,242,107,.24);border-radius:18px;box-shadow:0 34px 110px rgba(0,0,0,.7),0 0 90px rgba(216,242,107,.08);overflow:hidden;position:relative}
.command-panel:before{content:'';position:absolute;width:320px;height:180px;right:-90px;top:-100px;background:radial-gradient(circle,rgba(216,242,107,.14),transparent 68%);pointer-events:none}
.command-input-wrap{display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid var(--line);position:relative;z-index:1}
.command-input-wrap>span{color:var(--lime);font-size:16px;line-height:1}
#commandInput{flex:1;min-width:0;background:transparent;border:0;outline:0;color:var(--cream);font:500 13px var(--sans);letter-spacing:-.01em}
#commandInput::placeholder{color:#6d775f}
.command-input-wrap kbd{font:500 7px var(--mono);color:#8a947b;border:1px solid var(--line);border-radius:4px;padding:3px 5px;background:rgba(8,10,6,.4)}
.command-results{max-height:min(52vh,430px);overflow:auto;padding:7px;position:relative;z-index:1;scrollbar-width:thin}
.cmd-row{display:flex;align-items:center;gap:10px;width:100%;text-align:left;padding:8px 10px;border-radius:9px;border:1px solid transparent;background:transparent;transition:.12s}
.cmd-row:hover,.cmd-row.active{background:rgba(216,242,107,.07);border-color:rgba(216,242,107,.18)}
.cmd-row.active{box-shadow:inset 2px 0 var(--lime)}
.cmd-type{width:52px;flex-shrink:0;font:500 5.5px var(--mono);letter-spacing:.08em;color:#8b967d;border:1px solid var(--line);border-radius:4px;padding:3px 0;text-align:center}
.cmd-type-view{color:var(--lime);border-color:rgba(216,242,107,.24);background:rgba(216,242,107,.05)}
.cmd-type-course{color:#a9c98c}
.cmd-type-pdf{color:#9fb4c2}
.cmd-type-roadmap{color:#c3b19a}
.cmd-type-tag{color:#b9a6e6}
.cmd-copy{flex:1;min-width:0}
.cmd-copy b{display:block;font:600 10px var(--sans);color:#dbe3cf;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cmd-copy small{display:block;font:400 6.5px var(--mono);color:#79836a;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cmd-go{color:#6f7961;font:500 9px var(--mono);flex-shrink:0}
.cmd-row.active .cmd-go{color:var(--lime)}
.cmd-empty{display:flex;flex-direction:column;gap:5px;align-items:center;text-align:center;padding:30px 18px;color:#8a947c}
.cmd-empty b{font:400 15px var(--display);color:#c7d0b9}
.cmd-empty span{font:400 7px var(--mono);line-height:1.6}
.command-foot{display:flex;align-items:center;gap:13px;flex-wrap:wrap;padding:9px 15px;border-top:1px solid var(--line);font:400 6.5px var(--mono);color:#727c64;position:relative;z-index:1}
.command-foot b{color:#aab69a;font-weight:500}
.command-count{margin-left:auto;color:#8d977e}

