const hitCount = visible.reduce((n, x) => n + x.items.length, 0);
const hits = $('#roadmapHits');
if (hits) hits.textContent = query ? `${hitCount} hitos para “${query}”` : `${rp.total} hitos · ${R.streams.length} frentes · ${R.reverseEngineering?.length || 0} apps analizadas`;

