content.text:
.timelapse-events{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px;max-height:140px;overflow:auto;margin-top:3px}
.tl-event{display:flex;gap:6px;border:1px solid var(--line);border-radius:6px;background:rgba(8,10,6,.28);padding:5px 6px;text-align:left;min-width:0;transition:.15s}
.tl-event:hover{border-color:rgba(216,242,107,.24);background:rgba(216,242,107,.03)}
.tl-event-day{font:500 6px var(--mono);color:#93a47b;flex-shrink:0;padding-top:1px}
.tl-event-copy{min-width:0}
.tl-event-copy b{display:block;font:600 7.5px var(--sans);color:#b9c4a9;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tl-event-copy small{display:block;font-size:6.3px;line-height:1.35;color:#727c64;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tl-event.alert{border-color:rgba(232,181,106,.18)}
.tl-event.alert .tl-event-day{color:var(--amber)}
.tl-event.harvest,.tl-event.end{border-color:rgba(216,242,107,.2)}
.tl-event.harvest .tl-event-day,.tl-event.end .tl-event-day{color:var(--lime)}

/* ==========================================================================
   ROADMAP
   ========================================================================== */
.roadmap-head{margin-bottom:16px}
.roadmap-hero{display:grid;grid-template-columns:minmax(0,1.12fr) minmax(0,1.88fr);gap:10px;margin-bottom:10px}
.roadmap-north-card{background:linear-gradient(158deg,rgba(216,242,107,.07),var(--panel) 62%);border:1px solid rgba(216,242,107,.16);border-radius:18px;padding:16px 18px;overflow:hidden;display:flex;flex-direction:column}
.roadmap-north-card h2{font:400 26px/1.05 var(--display);letter-spacing:-.03em;margin:3px 0 7px;color:var(--cream);max-width:520px}
.roadmap-north-card p{font-size:9.5px;line-height:1.55;color:#98a28a;margin:0 0 13px;flex:1}
.roadmap-progress{height:4px;border-radius:4px;background:rgba(235,241,214,.08);overflow:hidden}
.roadmap-progress i{display:block;height:100%;background:linear-gradient(90deg,var(--lime),#8fce59);border-radius:4px;box-shadow:0 0 14px rgba(216,242,107,.5);transition:width .4s}
.roadmap-progress-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:6px;font:400 7px var(--mono);color:#7f886f}
.roadmap-progress-foot b{color:var(--lime);font-size:11px}
.roadmap-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
.roadmap-metric{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:8px 9px;min-width:0;display:flex;flex-direction:column;justify-content:space-between}
.roadmap-metric>span{display:block;font:400 5.8px var(--mono);letter-spacing:.04em;color:#737c66;text-transform:uppercase;line-height:1.35;min-height:15px}
.roadmap-metric b{display:block;font:400 16px/1.1 var(--display);letter-spacing:-.02em;color:#dde4cf;margin:2px 0 4px}
.roadmap-metric>i{display:block;height:2px;background:rgba(235,241,214,.08);border-radius:2px;overflow:hidden}
.roadmap-metric>i i{display:block;height:100%;background:var(--lime)}
.roadmap-metric small{display:block;font:400 5.5px var(--mono);color:#68715c;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

.roadmap-horizons{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin-bottom:10px}
.roadmap-horizon{position:relative;display:flex;align-items:flex-start;gap:7px;border:1px solid var(--line);background:var(--panel);border-radius:11px;padding:9px 10px;text-align:left;transition:.18s;overflow:hidden;min-width:0}
.roadmap-horizon:hover{border-color:var(--line-2)}
.roadmap-horizon.active{border-color:rgba(216,242,107,.4);background:rgba(216,242,107,.06)}
.rh-index{font:400 7px var(--mono);color:#66705a;border:1px solid var(--line);border-radius:3px;padding:1px 3px;flex-shrink:0}
.rh-copy{flex:1;min-width:0}
.rh-copy b{display:block;font:400 15px/1 var(--display);color:#dde4cf;margin-bottom:2px}
.rh-copy small{display:block;font:400 6px var(--mono);color:#7a836c;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rh-copy em{display:block;font-size:6.5px;line-height:1.35;color:#6e7761;font-style:normal;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rh-pct{font:400 15px var(--display);color:var(--lime);flex-shrink:0}
.rh-bar{position:absolute;left:0;right:0;bottom:0;height:2px;background:rgba(235,241,214,.06)}
.rh-bar i{display:block;height:100%;background:var(--lime)}

.roadmap-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:8px 0}
.roadmap-legend{display:flex;gap:9px;flex-wrap:wrap}
.roadmap-legend span{display:flex;align-items:center;gap:4px;font:400 6.5px var(--mono);letter-spacing:.04em;color:#858f76}
.roadmap-legend i{width:5px;height:5px;border-radius:50%}
.rs-done{background:var(--lime);box-shadow:0 0 6px rgba(216,242,107,.6)}
.rs-now{background:var(--amber)}
.rs-next{background:#9bb8c9}
.rs-later{background:#5a6350}
.roadmap-filters{display:flex;gap:4px;flex-wrap:wrap;flex:1;justify-content:center}
.road-filter{display:inline-flex;align-items:center;gap:4px;border:1px solid var(--line);background:transparent;border-radius:999px;padding:4px 8px;font:500 7px var(--sans);color:#9ba58b;transition:.15s}
.road-filter:hover{border-color:rgba(216,242,107,.28);color:var(--lime)}
.road-filter.active{background:var(--lime);border-color:var(--lime);color:#121708;font-weight:700}
.road-filter span{font-size:8px}
.road-filter em{font:400 5.8px var(--mono);font-style:normal;opacity:.7}
.roadmap-toolbar .toggle-btn{flex-shrink:0}

.roadmap-layout{display:grid;grid-template-columns:minmax(0,1.58fr) minmax(280px,.62fr);gap:10px;align-items:start}
.roadmap-streams{display:flex;flex-direction:column;gap:9px}
.road-stream{background:var(--panel);border:1px solid var(--line);border-radius:16px;overflow:hidden;--tone:lime}
.road-stream-head{display:flex;align-items:flex-start;gap:9px;padding:11px 13px 9px;background:linear-gradient(160deg,rgba(216,242,107,.03),transparent 70%);border-bottom:1px solid var(--line)}
.rs-icon{width:27px;height:27px;border-radius:8px;display:grid;place-items:center;background:rgba(216,242,107,.08);color:var(--lime);font-size:12px;flex-shrink:0}
.rs-copy{flex:1;min-width:0}
.rs-copy h3{font:400 17px/1.05 var(--display);letter-spacing:-.02em;margin:0 0 2px;color:#e5ead8}
.rs-copy p{font-size:7.5px;line-height:1.4;color:#7d876e;margin:0}
.rs-progress{text-align:right;flex-shrink:0;min-width:46px}
.rs-progress b{display:block;font:400 16px/1 var(--display);color:var(--lime);letter-spacing:-.03em}
.rs-progress small{display:block;font:400 5.8px var(--mono);color:#77816a;margin:1px 0 3px}
.rs-progress i{display:block;height:2px;width:46px;background:rgba(235,241,214,.08);border-radius:2px;overflow:hidden}
.rs-progress i i{display:block;height:100%;background:var(--tone)}
.road-items{padding:5px 7px 7px;display:grid;grid-template-columns:1fr 1fr;gap:3px 7px}
.road-item{display:grid;grid-template-columns:58px minmax(0,1fr);gap:6px;align-items:start;padding:5px 5px;border-radius:6px;border-bottom:1px solid rgba(235,241,214,.04);min-width:0;transition:.15s}
.road-item:hover{background:rgba(235,241,214,.025)}
.ri-status{display:flex;align-items:center;gap:4px;font:500 4.8px var(--mono);letter-spacing:.04em;color:#7b856d;white-space:nowrap;padding-top:2px}
.ri-status i{width:4px;height:4px;border-radius:50%;background:#5d6654;flex-shrink:0}
.road-item.done .ri-status{color:#a9c47a}
.road-item.done .ri-status i{background:var(--lime)}
.road-item.now .ri-status{color:var(--amber)}
.road-item.now .ri-status i{background:var(--amber);box-shadow:0 0 6px rgba(232,181,106,.5)}
.road-item.next .ri-status{color:#9bb8c9}
.road-item.next .ri-status i{background:#9bb8c9}
.ri-copy{min-width:0}
.ri-copy b{display:block;font:600 8.5px/1.3 var(--sans);color:#c5cfb6;letter-spacing:-.005em}
.ri-copy p{font-size:6.5px;line-height:1.4;color:#737d65;margin:1px 0 0}
.ri-meta{grid-column:2;display:flex;gap:3px;flex-wrap:wrap;margin-top:1px}
.ri-meta span{font:400 5.2px var(--mono);letter-spacing:.02em;color:#747e66;background:rgba(235,241,214,.04);border-radius:2px;padding:1px 3px;white-space:nowrap}
.ri-meta .ri-horizon{color:#92a97c}
.ri-meta .ri-effort{color:#c2a575}
.ri-meta .ri-metric{color:#8aa0a8}
.road-item.done .ri-copy b{color:#9ba78c}
.road-empty{grid-column:1/-1;padding:13px;text-align:center;font-size:8px;color:#7a846c}

.roadmap-side{display:flex;flex-direction:column;gap:9px;position:sticky;top:82px}
.roadmap-panel{padding:12px 13px;border-radius:14px}
.roadmap-panel-head{margin-bottom:7px}
.roadmap-panel-head h3{font:400 15px/1.1 var(--display);letter-spacing:-.02em;margin:1px 0 0;color:#e2e8d5}
.roadmap-principles{display:flex;flex-direction:column;gap:5px}
.roadmap-principles>div{display:flex;gap:6px;align-items:flex-start}
.roadmap-principles span{font:400 6px var(--mono);color:var(--lime);flex-shrink:0;padding-top:1px}
.roadmap-principles p{font-size:7.3px;line-height:1.4;color:#8a947b;margin:0}
.roadmap-nongoals{display:flex;flex-direction:column;gap:4px}
.roadmap-nongoals>div{display:flex;gap:6px;align-items:flex-start}
.roadmap-nongoals span{font:500 7px var(--mono);color:var(--danger);flex-shrink:0;line-height:1.3}
.roadmap-nongoals p{font-size:7.3px;line-height:1.4;color:#8a947b;margin:0}
.roadmap-risks{display:flex;flex-direction:column;gap:5px}
.road-risk{border-bottom:1px solid rgba(235,241,214,.05);padding-bottom:5px}
.road-risk:last-child{border-bottom:0;padding-bottom:0}
.road-risk>div{display:flex;align-items:center;justify-content:space-between;gap:6px}
.road-risk b{font:600 7.5px var(--sans);color:#b9c4a9}
.road-risk em{font:500 5.5px var(--mono);font-style:normal;padding:1px 3px;border-radius:2px;white-space:nowrap}
.risk-alto{color:#e08a72;background:rgba(224,138,114,.1)}
.risk-medio{color:var(--amber);background:rgba(232,181,106,.1)}
.risk-bajo{color:#a9c47a;background:rgba(216,242,107,.08)}
.road-risk p{font-size:6.8px;line-height:1.4;color:#747e66;margin:2px 0 0}
.roadmap-next-panel .btn{height:30px;font-size:8.5px;margin-top:8px}
#roadmapNext{display:flex;flex-direction:column;gap:4px}
.road-next-row{display:flex;gap:6px;align-items:flex-start;border-bottom:1px solid rgba(235,241,214,.05);padding-bottom:4px}

.road-next-row{display:flex;gap:6px;align-items:flex-start;border-bottom:1px solid rgba(235,241,214,.05);padding-bottom:4px}
.road-next-row:last-child{border-bottom:0}
.road-next-row>span{font-size:9px;color:var(--lime);flex-shrink:0;line-height:1.3}
.road-next-row b{display:block;font:600 7.5px/1.35 var(--sans);color:#bcc7ac}
.road-next-row small{display:block;font:400 5.5px var(--mono);color:#6f7961}

