.command-backdrop{align-items:flex-start;justify-content:center;padding:7vh 16px 20px;background:rgba(4,6,3,.74);backdrop-filter:blur(14px);z-index:90}
.command-panel{width:min(700px,100%);background:linear-gradient(165deg,#151b10,#0a0e07 72%);border:1px solid rgba(216,242,107,.24);border-radius:18px;box-shadow:0 34px 110px rgba(0,0,0,.7),0 0 90px rgba(216,242,107,.08);overflow:hidden;position:relative}
.command-panel:before{content:'';position:absolute;width:320px;height:180px;right:-90px;top:-100px;background:radial-gradient(circle,rgba(216,242,107,.14),transparent 68%);pointer-events:none}
.command-input-wrap{display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid var(--line);position:relative;z-index:1}
