.command-results{max-height:min(52vh,430px);overflow:auto;padding:7px;position:relative;z-index:1;scrollbar-width:thin}
.cmd-row{display:flex;align-items:center;gap:10px;width:100%;text-align:left;padding:8px 10px;border-radius:9px;border:1px solid transparent;background:transparent;transition:.12s}
.cmd-row:hover,.cmd-row.active{background:rgba(216,242,107,.07);border-color:rgba(216,242,107,.18)}
.cmd-row.active{box-shadow:inset 2px 0 var(--lime)}
.cmd-type{width:52px;flex-shrink:0;font:500 5.5px var(--mono);letter-spacing:.08em;color:#8b967d;border:1px solid var(--line);border-radius:4px;padding:3px 0;text-align:center}
.cmd-type-view{color:var(--lime);border-color:rgba(216,242,107,.24);background:rgba(216,242,107,.05)}
.cmd-type-course{color:#a9c98c}
.cmd-type-pdf{color:#9fb4c2}
.cmd-type-roadmap{color:#c3b19a}
.cmd-type-tag{color:#b9a6e6}
.cmd-copy{flex:1;min-width:0}
.cmd-copy b{display:block;font:600 10px var(--sans);color:#dbe3cf;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cmd-copy small{display:block;font:400 6.5px var(--mono);color:#79836a;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
