.cmd-empty b{font:400 15px var(--display);color:#c7d0b9}
.cmd-empty span{font:400 7px var(--mono);line-height:1.6}
.command-foot{display:flex;align-items:center;gap:13px;flex-wrap:wrap;padding:9px 15px;border-top:1px solid var(--line);font:400 6.5px var(--mono);color:#727c64;position:relative;z-index:1}
