.roadmap-reverse{margin:13px 0 11px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(160deg,rgba(216,242,107,.035),transparent 42%),var(--panel);padding:13px 14px 14px;overflow:hidden;min-width:0}
