.side-collapse{width:32px;height:32px;border-radius:10px;border:1px solid var(--line-2);background:rgba(216,242,107,.05);color:var(--lime);font-size:15px;line-height:1;flex-shrink:0;transition:.18s}
.side-collapse:hover{background:rgba(216,242,107,.14);box-shadow:0 0 18px rgba(216,242,107,.25)}
.side-label{display:flex;align-items:center;gap:9px;font-size:10.5px !important;font-weight:700 !important;letter-spacing:.18em !important;text-transform:uppercase;color:var(--lime) !important;margin:0 10px 10px !important;text-shadow:0 0 12px rgba(216,242,107,.35)}
.side-label i{flex:1;height:1px;background:linear-gradient(90deg,rgba(216,242,107,.38),transparent)}
.side-label:not(:first-child){margin-top:20px !important}
.side-label:before{content:'';width:6px;height:6px;border-radius:2px;background:var(--lime);box-shadow:0 0 10px rgba(216,242,107,.7);flex-shrink:0}
.sidebar{transition:width .25s ease}
.app{transition:grid-template-columns .25s ease}
body.side-collapsed .app{grid-template-columns:76px minmax(0,1fr)}
body.side-collapsed .sidebar{padding:22px 10px 14px}
body.side-collapsed .brand-type,body.side-collapsed .nav-text,body.side-collapsed .nav-item em,body.side-collapsed .nav-item .beta,body.side-collapsed .side-label>span,body.side-collapsed .side-label i,body.side-collapsed .legal-mini,body.side-collapsed .side-user-copy,body.side-collapsed .side-user .dots{display:none}
body.side-collapsed .brand{justify-content:center}
body.side-collapsed .side-label{justify-content:center;margin:0 0 8px !important}
body.side-collapsed .nav-item{justify-content:center;padding:0;height:44px}
body.side-collapsed .nav-ico{font-size:17px}
body.side-collapsed .side-collapse{width:40px;height:40px;margin:0 auto}
body.side-collapsed .side-user{justify-content:center;border-top:0;margin-top:8px;padding-top:8px}

/* ---- scrollbar ancha + glow en componentes ---- */
::-webkit-scrollbar{width:16px !important;height:16px !important}
::-webkit-scrollbar-thumb{background:#39442a !important;border-radius:10px !important;border:3px solid var(--bg) !important;box-shadow:inset 0 0 8px rgba(0,0,0,.5)}
::-webkit-scrollbar-thumb:hover{background:#5a6b3a !important;box-shadow:0 0 12px rgba(216,242,107,.25)}
.side-scroll{scrollbar-width:auto !important;overflow-y:auto !important}
.side-scroll::-webkit-scrollbar{display:block !important;width:10px !important}
.side-scroll::-webkit-scrollbar-thumb{background:#39442a !important;border-radius:6px !important}
.card,.panel,.batch-card,.idx-card,.strain-card,.road-stream,.lib-course-card,.strain-featured,.sim-config,.sim-results{box-shadow:0 0 0 rgba(216,242,107,0),0 18px 40px rgba(0,0,0,.18);transition:box-shadow .22s ease,border-color .22s ease,transform .22s ease}
.card:hover,.panel:hover,.idx-card:hover,.strain-card:hover,.lib-course-card:hover,.road-stream:hover,.sim-config:hover{border-color:rgba(216,242,107,.28) !important;box-shadow:0 0 24px rgba(216,242,107,.08),0 18px 44px rgba(0,0,0,.35)}
.batch-card:hover,.sim-results:hover{box-shadow:0 0 28px rgba(216,242,107,.1),0 18px 44px rgba(0,0,0,.35)}
.nav-item:hover{background:rgba(216,242,107,.06);box-shadow:0 0 16px rgba(216,242,107,.08)}
.btn:hover{box-shadow:0 0 18px rgba(216,242,107,.18)}
.btn-lime:hover{box-shadow:0 0 26px rgba(216,242,107,.4)}

/* ---- catálogo: 5 columnas, imágenes compactas, categorías y fuentes ---- */
.strain-grid{grid-template-columns:repeat(5,minmax(0,1fr)) !important;gap:10px !important}
