.strain-cat-tab:hover{border-color:rgba(216,242,107,.35);box-shadow:0 0 14px rgba(216,242,107,.12)}
.strain-cat-tab.active{background:var(--lime);border-color:var(--lime);box-shadow:0 0 20px rgba(216,242,107,.35)}
.strain-cat-tab.active b,.strain-cat-tab.active small{color:#121708}
.strain-source-tag{display:flex;align-items:center;gap:5px;font:500 7.5px var(--mono);color:#96a785;background:rgba(216,242,107,.05);border:1px solid rgba(216,242,107,.14);border-radius:5px;padding:3px 6px;min-width:0}
