.strain-featured-source span{letter-spacing:.08em;color:#7c866d}
.strain-sources{margin-top:14px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(160deg,rgba(216,242,107,.05),transparent 50%),var(--panel);padding:14px 15px;overflow:hidden}
.strain-sources-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;border-bottom:1px solid var(--line);padding-bottom:10px;margin-bottom:10px}
