.sim-config-grid{display:grid;grid-template-columns:minmax(0,2.2fr) repeat(4,minmax(0,.9fr));gap:8px;margin-bottom:10px}
.sim-field{display:flex;flex-direction:column;gap:4px;background:rgba(8,10,6,.5);border:1px solid var(--line);border-radius:10px;padding:8px 10px;min-width:0}
.sim-field>span{font:500 8.5px var(--mono);letter-spacing:.07em;text-transform:uppercase;color:#8d977e}
.sim-field .select,.sim-field input{width:100%;background:#0a0e07;border:1px solid var(--line);border-radius:8px;height:36px;padding:0 10px;color:var(--cream);font:600 11.5px var(--sans);outline:0;min-width:0}
.sim-field .select:focus,.sim-field input:focus{border-color:rgba(216,242,107,.45);box-shadow:0 0 0 2px rgba(216,242,107,.08)}
.sim-field small{font:400 8px/1.4 var(--mono);color:#6d7760;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sim-strategy-row{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;margin-bottom:10px}
.sim-strategy{background:rgba(8,10,6,.42);border:1px solid var(--line);border-radius:10px;padding:8px 9px;text-align:left;min-width:0;transition:.15s;display:flex;flex-direction:column;gap:2px}
.sim-strategy i{font-style:normal;font-size:13px;color:#8d977e}
.sim-strategy b{font:700 10.5px var(--sans);color:#cfd8c2;letter-spacing:-.01em}
.sim-strategy small{font-size:8.5px;line-height:1.4;color:#77816a}
.sim-strategy:hover{border-color:rgba(216,242,107,.3);box-shadow:0 0 16px rgba(216,242,107,.1)}
.sim-strategy.active{border-color:var(--lime);background:rgba(216,242,107,.07);box-shadow:0 0 20px rgba(216,242,107,.18)}
.sim-strategy.active i,.sim-strategy.active b{color:var(--lime)}
.sim-grades{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:6px}
.sim-grade{display:inline-flex;align-items:center;gap:5px;border:1px solid var(--line);background:rgba(8,10,6,.4);border-radius:999px;padding:5px 10px}
.sim-grade b{font:700 10px var(--sans);color:var(--gc)}
.sim-grade small{font:500 7.5px var(--mono);color:#77806a}
.sim-grades-note{font-size:9.5px;line-height:1.5;color:#8a947b}
.sim-config-note{font-size:10px;line-height:1.55;color:#828d76;margin:4px 0 0}
.sim-config-note b{color:#b9c4a9}
.sim-results{background:linear-gradient(158deg,#131a0f,#0d110b 70%);border:1px solid rgba(216,242,107,.2);border-radius:18px;padding:14px 15px 13px;margin-bottom:12px;box-shadow:0 0 50px rgba(216,242,107,.07)}
.sim-results-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:11px}
.sim-results-head h2{font:400 22px/1.05 var(--display);letter-spacing:-.025em;color:var(--cream);margin:2px 0 0}
.sim-result-stats{display:flex;gap:6px;flex-wrap:wrap}
.sim-stat{display:flex;flex-direction:column;align-items:flex-start;background:rgba(8,10,6,.5);border:1px solid var(--line);border-radius:10px;padding:7px 10px;min-width:86px}
.sim-stat b{font:400 16px/1.05 var(--display);letter-spacing:-.02em;color:#eef0dd}
.sim-stat small{font:400 7.5px var(--mono);letter-spacing:.05em;text-transform:uppercase;color:#77806a;margin-top:2px}
.sim-stat.grade b{color:var(--gc)}
.sim-stat.grade{border-color:color-mix(in srgb,var(--gc) 45%,transparent);box-shadow:0 0 20px color-mix(in srgb,var(--gc) 14%,transparent)}
.sim-chart-shell{display:grid;grid-template-columns:210px minmax(0,1fr);gap:10px}
.sim-chart-filters{background:rgba(8,10,6,.48);border:1px solid var(--line);border-radius:12px;padding:10px 10px 8px;min-width:0;align-self:start}
.sim-chart-filters>p{font-size:8.5px;line-height:1.5;color:#77816a;margin:4px 0 8px}
.sim-series-row{display:flex;align-items:center;gap:7px;padding:6px 7px;border-radius:8px;border:1px solid transparent;cursor:pointer;transition:.14s}
.sim-series-row:hover{background:rgba(216,242,107,.04);border-color:rgba(216,242,107,.16)}
.sim-series-row input{width:16px;height:16px;accent-color:var(--lime);flex-shrink:0}
.sim-series-swatch{color:var(--sc);font-size:12px;flex-shrink:0;width:14px;text-align:center;text-shadow:0 0 8px color-mix(in srgb,var(--sc) 60%,transparent)}
.sim-series-row b{display:block;font:700 10px var(--sans);color:#cfd8c2}
.sim-series-row small{display:block;font:400 7.5px var(--mono);color:#6d7760}
.sim-chart-main{background:rgba(8,10,6,.42);border:1px solid var(--line);border-radius:12px;padding:10px 12px;min-width:0}
.sim-chart-title-row{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:6px}
.sim-chart-title-row h3{font:400 17px/1.1 var(--display);letter-spacing:-.02em;color:#e6ebd9;margin:0}
.sim-chart-title-row span{font:400 8.5px var(--mono);color:#77806a}
.sim-chart-flex{display:flex;gap:10px;align-items:stretch}
.sim-svg{flex:1;min-width:0;width:100%;height:auto;display:block}
.sim-chart-legend{width:128px;flex-shrink:0;border-left:1px solid var(--line);padding-left:10px;display:flex;flex-direction:column;gap:6px}
.sim-legend-row{display:flex;align-items:center;gap:6px;font-size:10.5px;color:#b7c2a6}
.sim-legend-mark{color:var(--sc);font-size:12px;text-shadow:0 0 8px color-mix(in srgb,var(--sc) 60%,transparent)}
.sim-chart-empty{font-size:10px;line-height:1.5;color:#77816a}
.sim-process{list-style:none;margin:12px 0 0;padding:0;border-top:1px solid var(--line);display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0}
.sim-step{display:flex;align-items:flex-start;gap:8px;padding:8px 8px 8px 0;border-bottom:1px solid rgba(235,241,214,.05);min-width:0}
.sim-step-day{font:500 8.5px var(--mono);color:var(--lime);flex-shrink:0;padding-top:1px;min-width:32px}
.sim-step-phase{font:500 7px var(--mono);letter-spacing:.05em;text-transform:uppercase;color:#77806a;flex-shrink:0;padding-top:2px;max-width:74px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sim-step-copy{flex:1;min-width:0}
.sim-step-copy b{display:block;font:700 10px var(--sans);color:#cfd8c2}
.sim-step-copy small{display:block;font-size:9px;line-height:1.45;color:#77816a}
.sim-step-state{font:500 7.5px var(--mono);color:#7a846c;flex-shrink:0}
.sim-step.skipped{opacity:.55}
.sim-step.skipped .sim-step-state{color:#8a715f}

@media(max-width:1280px){
  .strain-grid{grid-template-columns:repeat(4,minmax(0,1fr)) !important}
  .sim-strategy-row{grid-template-columns:repeat(3,minmax(0,1fr))}
  .sim-config-grid{grid-template-columns:minmax(0,1.6fr) repeat(2,minmax(0,1fr))}
}
@media(max-width:1080px){
  .strain-grid{grid-template-columns:repeat(3,minmax(0,1fr)) !important}
  .strain-sources-grid{grid-template-columns:1fr}
  .sim-chart-shell{grid-template-columns:1fr}
  .sim-chart-filters{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
  .sim-chart-filters .section-kicker,.sim-chart-filters>p{flex:1 1 100%}
  .sim-series-row{flex:1 1 calc(33% - 6px)}
  .sim-config-grid{grid-template-columns:1fr 1fr}
}
@media(max-width:960px){
  .strain-grid{grid-template-columns:repeat(2,minmax(0,1fr)) !important}
  .sim-strategy-row{grid-template-columns:repeat(2,minmax(0,1fr))}
  .sim-process{grid-template-columns:1fr}
  .sim-chart-flex{flex-direction:column}
  .sim-chart-legend{width:100%;border-left:0;border-top:1px solid var(--line);padding:8px 0 0;flex-direction:row;flex-wrap:wrap}
  body.side-collapsed .app{grid-template-columns:minmax(0,1fr)}
  body.side-collapsed .sidebar{display:none}
}
@media(max-width:700px){
  .strain-grid{grid-template-columns:repeat(2,minmax(0,1fr)) !important;gap:8px !important}
  .strain-grid .strain-card-media{height:110px !important}
  .sim-config-grid{grid-template-columns:1fr}
  .sim-strategy-row{grid-template-columns:1fr 1fr}
  .sim-result-stats{width:100%}
  .sim-stat{flex:1 1 30%}
  .brand-row .side-collapse{display:none}
  body.side-collapsed .brand-row .side-collapse{display:block}
}
EOF
