210:.lib-mode b{display:block;font:600 10px var(--sans);color:#d3dac6}
220:.digest-copy h2{font:400 24px/1.05 var(--display);letter-spacing:-.03em;margin:2px 0 7px}
221:.digest-copy h2 em{font-style:italic;font-weight:300;color:var(--lime)}
699:  .digest-copy h2{font-size:21px}
993:.lib-cover{width:62px;height:82px;border-radius:8px;flex-shrink:0;display:flex;flex-direction:column;justify-content:space-between;padding:7px 7px 6px;background:linear-gradient(155deg,var(--cc),#0d110b 85%);border:1px solid color-mix(in srgb,var(--cc) 55%,transparent);box-shadow:0 6px 18px rgba(0,0,0,.35);color:#eef0dd;overflow:hidden;position:relative}
994:.lib-cover:before{content:'';position:absolute;left:0;right:0;top:0;height:14px;background:rgba(0,0,0,.28)}
995:.lib-cover i{font:700 7px var(--mono);letter-spacing:.12em;font-style:normal;color:var(--lime);position:relative}
996:.lib-cover b{font:600 8.5px/1.25 var(--sans);color:#f2efdf;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
997:.lib-cover small{font:400 7px var(--mono);color:rgba(242,239,223,.72);position:relative}
998:.lib-cover em{font:700 7px var(--mono);font-style:normal;color:#0d110b;background:var(--lime);border-radius:4px;padding:1px 4px;align-self:flex-start;position:relative}
1001:.emergent-guide{margin-top:12px;border:1px solid rgba(216,242,107,.18);border-radius:16px;background:linear-gradient(160deg,rgba(216,242,107,.045),transparent 55%),var(--panel);padding:13px 14px}
1002:.emergent-head h3{font:400 18px/1.1 var(--display);letter-spacing:-.02em;color:#e6ebd9;margin:2px 0 0}
1003:.emergent-head h3 em{font-style:italic;color:var(--lime)}
1004:.emergent-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:10px}
1005:.emergent-card{background:rgba(8,10,6,.48);border:1px solid var(--line);border-radius:12px;padding:10px 11px;min-width:0}
1006:.emergent-kicker{font:600 7px var(--mono);letter-spacing:.1em;color:var(--lime)}
1007:.emergent-card>b{display:block;font:700 11px var(--sans);color:#d6dfc9;margin:4px 0 5px;line-height:1.35}
1008:.emergent-card>p{font-size:9.5px;line-height:1.55;color:#8b947e;margin:0 0 8px}
1009:.emergent-list{display:flex;flex-direction:column;gap:5px}
1010:.emergent-list button{text-align:left;background:rgba(235,241,214,.03);border:1px solid var(--line);border-radius:8px;padding:7px 8px;transition:.14s;font-size:10px;color:#b7c2a6}

